/* Private template assets are independent of resume facts and marketplace purchases. */
state.privateTemplates??=[];
state.defaultTemplate??='classic';
let templateView='market',pendingTemplate=null,templateReturn=null;
const defaultDesign={layout:'classic',accent:'#2855e7',fontFamily:'sans',fontSize:13,lineHeight:1.6,pageMargin:18};
function templateDesign(id){const own=state.privateTemplates.find(t=>t.id===id&&t.status==='ready');if(own)return own.design;return {...defaultDesign,layout:['classic','modern','serif'].includes(id)?id:'modern',fontFamily:id==='serif'?'serif':'sans'}}
function availableTemplates(){return [...templates,...state.privateTemplates.filter(t=>t.status==='ready').map(t=>({id:t.id,name:t.name,hint:'个人模板',cost:'自有 · 私有'}))]}
function downloadTemplateFile(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function packageTemplate(t){return {type:'qicheng-template',schemaVersion:1,name:t.name,design:clone(t.design)}}
function validateTemplate(obj){if(!obj||typeof obj!=='object'||Array.isArray(obj))throw Error('文件必须是模板 JSON 对象。');if(obj.type!=='qicheng-template'||obj.schemaVersion!==1)throw Error('这不是启程模板 v1。JSON Resume 属于简历内容格式，不能直接当成版式。可下载示例查看规范。');if(typeof obj.name!=='string'||!obj.name.trim()||obj.name.length>80)throw Error('请填写 1–80 字的模板名称。');const d=obj.design;if(!d||!['classic','modern','serif'].includes(d.layout))throw Error('design.layout 需为 classic、modern 或 serif。');if(!/^#[0-9a-f]{6}$/i.test(d.accent))throw Error('主题色需为 #RRGGBB 格式。');if(!['sans','serif'].includes(d.fontFamily))throw Error('字体需为 sans 或 serif。');for(const [k,min,max] of [['fontSize',11,18],['lineHeight',1.2,2],['pageMargin',10,25]])if(typeof d[k]!=='number'||!Number.isFinite(d[k])||d[k]<min||d[k]>max)throw Error(`${k} 必须为 ${min}–${max} 的数值。`);return {name:obj.name.trim(),design:{layout:d.layout,accent:d.accent,fontFamily:d.fontFamily,fontSize:d.fontSize,lineHeight:d.lineHeight,pageMargin:d.pageMargin}}}
const beforeTemplatesPaper=resumePaper;
resumePaper=function(r){const spec=r.templateSpec||(state.privateTemplates.find(t=>t.id===r.template&&t.status==='ready')?.design);if(!spec)return beforeTemplatesPaper(r);const base=beforeTemplatesPaper({...r,template:spec.layout});return base.replace('class="resume-paper',`style="--tpl-accent:${spec.accent};--tpl-size:${spec.fontSize}px;--tpl-leading:${spec.lineHeight};--tpl-margin:${spec.pageMargin}mm;--tpl-font:${spec.fontFamily==='serif'?"Georgia, 'Songti SC', serif":"Arial, 'PingFang SC', sans-serif"}" class="resume-paper custom-template`)};
function templatePreview(t){const fake={person:'你的姓名',headline:'求职方向 · 技术关键词',education:'学校 / 专业 / 学位 / 时间',contact:'邮箱 · 所在城市',skills:'用自己的技能替换此处',experiences:[{title:'项目 / 工作经历',date:'起止时间',body:'展示你自己的职责、技术决策与成果。模板只定义排版，不提供别人的经历。',visible:true}],template:t.design.layout,templateSpec:t.design};return `<div class="template-preview">${resumePaper(fake)}</div>`}
function templateLibrary(){return head('我的模板','内置、自己导入、自己设计。模板不会自动公开或上架。',act('template-create','自定义模板','btn')+act('template-import',I('plus')+' 导入模板','btn primary'))+`<div class="note" style="margin-bottom:22px">初始默认：中文 A4 单栏 · 内容与版式分开保存 · 投递导出 PDF。你可以将喜欢的模板设为默认。</div><div class="template-library-grid">${availableTemplates().map(t=>{const own=state.privateTemplates.find(x=>x.id===t.id);return `<section class="card"><div class="row between"><h2>${E(t.name)}</h2>${pill(state.defaultTemplate===t.id?'默认模板':own?'个人私有':'内置',state.defaultTemplate===t.id?'blue':'')}</div><div class="template-thumb ${own?.design.layout||t.id}" style="margin:20px 0">Aa<br><i></i><i></i><i></i></div><p class="label">${E(own?.sourceName||t.hint||'个人版式')} · 可编辑</p><div class="row" style="margin-top:18px">${act('template-preview','预览','btn sm',`data-id="${t.id}"`)}${act('template-default','设为默认','btn sm',`data-id="${t.id}"`)}${act('template-use','用它新建','btn sm primary',`data-id="${t.id}"`)}${act('template-export','导出模板','text-btn',`data-id="${t.id}"`)}${own?act('template-remove','移除','text-btn',`data-id="${t.id}"`):''}</div></section>`}).join('')}</div><section class="card" style="margin-top:24px"><h2>外部模板源文件</h2><p class="label">LaTeX、Typst、RenderCV YAML、HTML 等先保留源码，适配后才能用于可视化编辑。原型不会运行外部代码或伪装编译预览。</p>${state.privateTemplates.filter(t=>t.status==='source').map(t=>`<div class="task"><div class="grow"><h3>${E(t.name)}</h3><p class="meta">${E(t.sourceName)} · ${E(t.format)} · 待适配</p></div>${act('template-source','查看源码','btn sm',`data-id="${t.id}"`)}${act('template-adapt','创建适配副本','btn sm',`data-id="${t.id}"`)}${act('template-remove','移除','text-btn',`data-id="${t.id}"`)}</div>`).join('')||'<p class="empty">还没有导入外部源文件。</p>'}</section>`}
const templateMarketBase=market;
market=function(){return `<div class="tabs compact template-tabs">${act('template-view','模板与简历市场',templateView==='market'?'active':'','data-id="market"')}${act('template-view','我的模板',templateView==='mine'?'active':'','data-id="mine"')}</div>`+(templateView==='mine'?templateLibrary():`<div class="personal-template-banner"><span>已经有喜欢的模板？直接使用自己的。</span><div class="row">${act('template-import','导入模板','btn')}${act('my-templates','我的模板','text-btn')}</div></div>`+templateMarketBase())};
function openTemplateImport(){pendingTemplate=null;modal('导入自己的模板',`<p>模板保存在当前浏览器的私人模板库，不需要通过市场购买。</p><label class="field" style="margin-top:18px"><span>选择模板文件</span><input id="template-file" type="file" accept=".json,.tex,.typ,.yaml,.yml,.html,.htm,.md,.markdown"></label><p class="meta">文本文件，最多 512 KB。原型仅在本机读取，不会上传。</p><div class="note"><strong>可直接使用：</strong>启程模板 JSON v1。<br><strong>保存源码待适配：</strong>LaTeX / Typst / YAML / HTML / Markdown。<br>PDF 是输出文件；DOCX、ZIP 完整工程的适配留待正式实现，当前不支持。</div><div class="row" style="margin-top:16px">${act('template-example','下载模板示例','text-btn')}${act('template-paste','粘贴模板 JSON','text-btn')}</div><div id="template-import-result" aria-live="polite"></div>`,act('close','取消','btn')+act('template-save','确认导入','btn primary','id="template-import-save" disabled'));document.getElementById('template-file').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;pendingTemplate=null;document.getElementById('template-import-save').disabled=true;const result=document.getElementById('template-import-result');result.textContent='正在读取…';try{if(f.size>512*1024)throw Error('文件超过 512 KB。请只选择模板文本文件。');const ext=f.name.split('.').pop().toLowerCase(),raw=await f.text();if(ext==='json'){const t=validateTemplate(JSON.parse(raw));pendingTemplate={...t,status:'ready',sourceName:f.name}}else{if(!['tex','typ','yaml','yml','html','htm','md','markdown'].includes(ext))throw Error('暂不支持此格式，请导入模板 JSON 或受支持的文本源码。');if(!raw.trim()||raw.includes('\u0000'))throw Error('文件为空或不是可读文本源码。');pendingTemplate={name:f.name.replace(/\.[^.]+$/,''),sourceName:f.name,source:raw,format:ext,status:'source'}}result.innerHTML=`<div class="note" style="margin-top:18px"><strong>${E(pendingTemplate.name)}</strong><br>${pendingTemplate.status==='ready'?'校验通过，可用于创建和编辑简历。':'仅保存原始源码，不执行。导入后会标记为待适配。'}</div>`;document.getElementById('template-import-save').disabled=false}catch(err){result.innerHTML=`<p class="error">${E(err instanceof SyntaxError?'JSON 格式错误，请检查引号与逗号。':err.message)}</p>`}}}
function createTemplate(sourceId){const src=state.privateTemplates.find(t=>t.id===sourceId);formModal(src?'创建可视化适配副本':'自定义自己的模板',field('模板名称','name',src?src.name+' · 可视化版':'我的模板')+selectField('基础版式','layout',[['classic','中文单栏'],['modern','蓝线强调'],['serif','经典衬线']],'classic')+selectField('字体风格','fontFamily',[['sans','无衬线'],['serif','衬线']],'sans')+`<div class="two-col">${field('主题色','accent','#2855e7','color')}${field('正文字号（11–18 px）','fontSize',13,'number')}</div><div class="two-col"><label class="field"><span>行高（1.2–2）</span><input name="lineHeight" type="number" min="1.2" max="2" step="0.1" value="1.6" required></label>${field('页边距（10–25 mm）','pageMargin',18,'number')}</div><p class="note">${src?'这是你手动建立的版式副本，不代表系统已转换原始源码。源文件继续保留供对照。':'只保存排版，不包含你的姓名、联系方式或经历。'}</p>`,'预览并确认',f=>{try{const obj={type:'qicheng-template',schemaVersion:1,name:f.get('name'),design:{layout:f.get('layout'),accent:f.get('accent'),fontFamily:f.get('fontFamily'),fontSize:Number(f.get('fontSize')),lineHeight:Number(f.get('lineHeight')),pageMargin:Number(f.get('pageMargin'))}};pendingTemplate={...validateTemplate(obj),status:'ready',sourceName:src?'手动适配自 '+src.sourceName:'自行设计',sourceId:src?.id};modal('确认模板版式',templatePreview(pendingTemplate),act('template-create','重新设置','btn')+act('template-save','保存到我的模板','btn primary'));document.getElementById('dialog').classList.add('wide')}catch(err){document.getElementById('form-error').textContent=err.message}})}
function saveImportedTemplate(){if(!pendingTemplate)return;const t={id:'private-'+uid(),...clone(pendingTemplate)};state.privateTemplates.push(t);try{localStorage.setItem('qicheng-prototype-v1',JSON.stringify({...state,mode}))}catch{state.privateTemplates.pop();toast('本机存储空间不足，模板未保存。请先导出并清理不需要的内容。');return}pendingTemplate=null;close();if(templateReturn&&t.status==='ready'){const ctx=templateReturn;templateReturn=null;resumeWizard(ctx.source,ctx.jobId);if(ctx.name)document.querySelector('#modal-form [name="name"]').value=ctx.name;document.querySelector(`[name="template"][value="${t.id}"]`).checked=true;toast('已导入并选中自己的模板');return}templateReturn=null;templateView='mine';go('market');toast(t.status==='ready'?'模板已保存，可以用它创建简历':'源文件已保存，当前状态：待适配')}
const beforeTemplatesWizard=resumeWizard;
resumeWizard=function(source='',jobId=''){beforeTemplatesWizard(source,jobId);resumeWizard.context={source,jobId}};
const beforeTemplateAction=action;
action=function(a,d={}){
 switch(a){
 case 'template-view':templateView=d.id;render();return;
 case 'my-templates':templateView='mine';close();go('market');return;
 case 'template-import':templateReturn=document.querySelector('#modal-form [name="template"]')?{...resumeWizard.context,source:document.querySelector('#modal-form [name="source"]').value,name:document.querySelector('#modal-form [name="name"]').value}:null;openTemplateImport();return;
 case 'template-paste':formModal('粘贴模板 JSON',textField('模板 JSON','json','','粘贴启程模板 v1 JSON；不会执行脚本'),'校验并预览',f=>{try{pendingTemplate={...validateTemplate(JSON.parse(f.get('json'))),status:'ready',sourceName:'粘贴导入'};modal('模板校验通过',templatePreview(pendingTemplate),act('close','取消','btn')+act('template-save','确认导入','btn primary'));document.getElementById('dialog').classList.add('wide')}catch(err){document.getElementById('form-error').textContent=err instanceof SyntaxError?'JSON 格式错误，请检查引号与逗号。':err.message}});return;
 case 'template-example':downloadTemplateFile('qicheng-template-example.json',JSON.stringify({type:'qicheng-template',schemaVersion:1,name:'我的中文单栏模板',design:defaultDesign},null,2));return;
 case 'template-save':saveImportedTemplate();return;
 case 'template-create':templateReturn=null;createTemplate();return;
 case 'template-adapt':templateReturn=null;createTemplate(d.id);return;
 case 'template-default':state.defaultTemplate=d.id;persist();render();toast('下次新建默认选用此模板，已有简历不变');return;
 case 'template-use':close();resumeWizard();document.querySelector(`[name="template"][value="${d.id}"]`).checked=true;return;
 case 'template-preview':{const t=availableTemplates().find(t=>t.id===d.id);modal(E(t.name),templatePreview({design:templateDesign(t.id)}),act('close','关闭','btn')+act('template-use','用它新建简历','btn primary',`data-id="${t.id}"`));document.getElementById('dialog').classList.add('wide');return}
 case 'template-export':{const t=availableTemplates().find(t=>t.id===d.id);downloadTemplateFile(t.name+'.json',JSON.stringify(packageTemplate({name:t.name,design:templateDesign(t.id)}),null,2));return}
 case 'template-source':{const t=state.privateTemplates.find(t=>t.id===d.id);modal(E(t.sourceName),`<p class="note">原始源码，仅以文本查看；未执行或编译。</p><pre class="template-source">${E(t.source)}</pre>`,act('template-source-export','下载原文件','btn',`data-id="${t.id}"`));document.getElementById('dialog').classList.add('wide');return}
 case 'template-source-export':{const t=state.privateTemplates.find(t=>t.id===d.id);downloadTemplateFile(t.sourceName,t.source,'text/plain');return}
 case 'template-remove':modal('移除个人模板？','<p>已有简历保留创建时的版式快照。若是默认模板，将恢复为中文单栏。建议先导出模板留存。</p>',act('close','取消','btn')+act('template-remove-confirm','移除模板','btn danger',`data-id="${d.id}"`));return;
 case 'template-remove-confirm':state.privateTemplates=state.privateTemplates.filter(t=>t.id!==d.id);if(state.defaultTemplate===d.id)state.defaultTemplate='classic';persist();close();render();return;
 case 'reset-confirm':beforeTemplateAction(a,d);state.privateTemplates=[];state.defaultTemplate='classic';templateView='market';persist();render();return;
 }
 beforeTemplateAction(a,d);
};
render();
